-- Tenant accounts are provisioned explicitly by staff; no property record creates an identity.
CREATE TABLE IF NOT EXISTS tenant_accounts (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT, active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tenant_assignments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant_accounts(id), building_id TEXT NOT NULL REFERENCES buildings(id), unit_id TEXT NOT NULL REFERENCES units(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(tenant_id,unit_id));
CREATE INDEX IF NOT EXISTS idx_tenant_assignments_tenant ON tenant_assignments(tenant_id,active);
CREATE TABLE IF NOT EXISTS tenant_login_codes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant_accounts(id), code_hash TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_tenant_login_codes_tenant ON tenant_login_codes(tenant_id,created_at);
CREATE TABLE IF NOT EXISTS tenant_login_throttle (key_hash TEXT PRIMARY KEY, window_start TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tenant_sessions (token_hash TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant_accounts(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_tenant_sessions_tenant ON tenant_sessions(tenant_id,expires_at);
CREATE TABLE IF NOT EXISTS tenant_maintenance_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant_accounts(id), assignment_id TEXT NOT NULL REFERENCES tenant_assignments(id), category TEXT NOT NULL, description TEXT NOT NULL, urgency TEXT NOT NULL CHECK(urgency IN ('routine','urgent')), preferred_contact TEXT NOT NULL CHECK(preferred_contact IN ('email','phone')), status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','in_review','scheduled','completed','closed')), staff_notes TEXT, submitted_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_tenant_requests_tenant ON tenant_maintenance_requests(tenant_id,submitted_at);
CREATE TABLE IF NOT EXISTS tenant_documents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant_accounts(id), assignment_id TEXT REFERENCES tenant_assignments(id), title TEXT NOT NULL, document_type TEXT NOT NULL, private_storage_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tenant_contact_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant_accounts(id), assignment_id TEXT NOT NULL REFERENCES tenant_assignments(id), subject TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', staff_notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
